/* ═══ Onderbalk in licht thema (v212) ═══ */
@media (prefers-color-scheme:light){
  :root:not([data-theme="dark"]) #pill-nav{background:rgba(255,255,255,.9);border-color:rgba(0,0,0,.08);box-shadow:0 4px 24px rgba(0,0,0,.12),0 1px 3px rgba(0,0,0,.06)}
  :root:not([data-theme="dark"]) .pn-tab{color:rgba(0,0,0,.42)}
  :root:not([data-theme="dark"]) .pn-tab.active{color:var(--text-on-fill)}
  :root:not([data-theme="dark"]) #pn-settings.has-badge::after{box-shadow:0 0 0 2px #fff}
}
:root[data-theme="light"] #pill-nav{background:rgba(255,255,255,.9);border-color:rgba(0,0,0,.08);box-shadow:0 4px 24px rgba(0,0,0,.12),0 1px 3px rgba(0,0,0,.06)}
:root[data-theme="light"] .pn-tab{color:rgba(0,0,0,.42)}
:root[data-theme="light"] .pn-tab.active{color:var(--text-on-fill)}
:root[data-theme="light"] #pn-settings.has-badge::after{box-shadow:0 0 0 2px #fff}
